#include "processing_step.hpp"

#include <SeQuant/core/utility/exception.hpp>

#include <string>

namespace sequant::util::extint {

ProcessingStep::~ProcessingStep() = default;

namespace detail {

std::optional<std::string_view> strip_autogenerated_id(std::string_view id) {
  if (auto pos = id.find('.'); pos != std::string_view::npos) {
    // Remove step ID of previous step
    id = id.substr(pos);
  }

  if (id.empty() ||
      id.substr(1).find_first_not_of("0123456789") == std::string_view::npos) {
    // "Trivial" (autogenerated) IDs aren't worth preserving as aliases
    return std::nullopt;
  }

  return id;
}

std::string make_output_range_id(std::string_view step_id, std::size_t start,
                                 std::size_t count) {
  return std::string(step_id) + "[" + std::to_string(start) + "-" +
         std::to_string(start + count - 1) + "]";
}

std::string make_group_alias(std::string_view step_id,
                             std::string_view group_id) {
  if (auto pos = group_id.find('.'); pos != std::string_view::npos) {
    // Remove previous step ID
    return std::string(step_id) + std::string(group_id.substr(pos));
  }

  return std::string(step_id) + "." + std::string(group_id);
}

void alias_individual_ids(ExecutionContext &ctx, std::string_view step_id,
                          const std::vector<std::string_view> &associated_ids,
                          std::string_view target_id) {
  for (std::string_view assoc_id : associated_ids) {
    std::optional<std::string_view> suffix = strip_autogenerated_id(assoc_id);
    if (!suffix) {
      continue;
    }

    std::string alias = std::string(step_id) + std::string(*suffix);

    if (ctx.has_data(alias)) {
      if (!ctx.ids_are_equivalent(target_id, alias)) {
        throw Exception("Duplicate ID name '" + std::string(*suffix) +
                        "' leading to ambiguity for '" + alias + "'");
      }

      continue;
    }

    ctx.add_data_alias(target_id, std::move(alias));
  }
}

AliasPropagator::AliasPropagator(ExecutionContext &ctx,
                                 std::string_view step_id)
    : ctx_(ctx), step_id_(step_id) {}

void AliasPropagator::record(
    const std::vector<std::string_view> &associated_ids,
    const std::vector<std::string_view> &associated_group_ids,
    std::size_t start, std::size_t count, bool alias_source) {
  if (count == 0) {
    return;
  }

  if (alias_source) {
    SEQUANT_ASSERT(count == 1);
    ctx_.add_data_alias(associated_ids.front(),
                        std::string(step_id_) + "." + std::to_string(start));
  }

  std::string created_outputs = make_output_range_id(step_id_, start, count);

  alias_individual_ids(ctx_, step_id_, associated_ids, created_outputs);

  for (std::string_view group_id : associated_group_ids) {
    group_assocs_[group_id].emplace_back(created_outputs);
  }
}

void AliasPropagator::flush() {
  for (auto &[group_id, assoc_outputs] : group_assocs_) {
    const std::size_t expected_size = ctx_.dataset_size(group_id);
    SEQUANT_ASSERT(expected_size >= assoc_outputs.size());

    if (expected_size != assoc_outputs.size()) {
      continue;
    }

    std::string out_group_id = make_group_alias(step_id_, group_id);

    if (ctx_.has_data(out_group_id)) {
      if (!ctx_.ids_are_equivalent(assoc_outputs, out_group_id)) {
        throw Exception("Duplicate group ID name '" + std::string(group_id) +
                        "' leading to ambiguity for '" + out_group_id + "'");
      }

      continue;
    }

    ctx_.add_data_alias(assoc_outputs, std::move(out_group_id));
  }
}

}  // namespace detail

}  // namespace sequant::util::extint
